window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0846cb7761e0b7bf"]={"versions": [{"id": "FIG-0846cb7761e0b7bf", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der LIN-Kommunikationsinfrastruktur innerhalb des AUTOSAR-System-Templates (Fibex4Lin-Topologie). Das Diagramm spezialisiert die generische Topologie-Definition von Kommunikations-Controllern für LIN-spezifische Master- und Slave-Knoten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>CoreTopology::CommunicationController</code></strong> (spezialisiert <code>Identifiable</code>): Abstrakte Basisklasse für Kommunikationscontroller im Topologiemodell. Besitzt das Attribut <code>+ wakeUpByControllerSupported: Boolean</code>.\n</li><li><strong><code>LinCommunicationController</code></strong> (kursiv dargestellt, abstrakt): Spezialisiert <code>CommunicationController</code> via Generalisierung; dient als Basis für LIN-Knotenrollen ohne eigene deklarierte Attribute.\n</li><li><strong><code>LinMaster</code></strong>: Spezialisiert <code>LinCommunicationController</code>. Enthält die optionalen Attribute:\n<ul class=\"fig-list\"><li><code>+ timeBase: Float [0..1]</code>\n</li><li><code>+ timeBaseJitter: Float [0..1]</code>\n</li></ul>\n</li><li><strong><code>LinSlave</code></strong>: Spezialisiert <code>LinCommunicationController</code>. Enthält die Attribute:\n<ul class=\"fig-list\"><li><code>+ configuredNad: Int</code>\n</li><li><code>+ protocolVersion: String</code>\n</li></ul>\n</li><li><strong><code>LinCommunication::LinErrorResponse</code></strong>: Über eine gerichtete Komposition (<code>LinSlave</code> als Ganzes, gefüllte Raute) mit der Rollenbezeichnung <code>+linErrorResponse</code> und Kardinalität <code>1</code> an <code>LinSlave</code> gebunden. Besitzt das Attribut:\n<ul class=\"fig-list\"><li><code>+ responseErrorPosition: Int</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzspezifikation. Das Diagramm modelliert Konfigurationsstrukturen für den LIN-Bus; die Parameter steuern die zeitliche Basis für das Scheduling des LIN-Masters sowie Fehleranzeigeposition und Knotenadressierung (NAD) auf Slave-Seite.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die AUTOSAR-Systembeschreibung (System Template). Bei der Konfiguration eines LIN-Clusters müssen Instanzen entweder als <code>LinMaster</code> oder <code>LinSlave</code> ausgeprägt werden. Ein <code>LinSlave</code> verlangt zwingend genau eine komponierte <code>LinErrorResponse</code> (Kardinalität 1) zur Festlegung der Fehlerposition im LIN-Frame. Die Zeitbasis-Attribute des Masters sind optional ([0..1]).</p>"}, {"id": "FIG-27ed5701146fecd2", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der LIN-Kommunikationsinfrastruktur innerhalb des AUTOSAR-System-Templates (Fibex4Lin-Topologie). Das Diagramm spezialisiert die generische Topologie-Definition von Kommunikations-Controllern für LIN-spezifische Master- und Slave-Knoten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>CoreTopology::CommunicationController</code></strong> (spezialisiert <code>Identifiable</code>): Abstrakte Basisklasse für Kommunikationscontroller im Topologiemodell. Besitzt das Attribut <code>+ wakeUpByControllerSupported: Boolean</code>.\n</li><li><strong><code>LinCommunicationController</code></strong> (kursiv dargestellt, abstrakt): Spezialisiert <code>CommunicationController</code> via Generalisierung; dient als Basis für LIN-Knotenrollen ohne eigene deklarierte Attribute.\n</li><li><strong><code>LinMaster</code></strong>: Spezialisiert <code>LinCommunicationController</code>. Enthält die optionalen Attribute:\n<ul class=\"fig-list\"><li><code>+ timeBase: Float [0..1]</code>\n</li><li><code>+ timeBaseJitter: Float [0..1]</code>\n</li></ul>\n</li><li><strong><code>LinSlave</code></strong>: Spezialisiert <code>LinCommunicationController</code>. Enthält die Attribute:\n<ul class=\"fig-list\"><li><code>+ configuredNad: Int</code>\n</li><li><code>+ protocolVersion: String</code>\n</li></ul>\n</li><li><strong><code>LinCommunication::LinErrorResponse</code></strong>: Über eine gerichtete Komposition (<code>LinSlave</code> als Ganzes, gefüllte Raute) mit der Rollenbezeichnung <code>+linErrorResponse</code> und Kardinalität <code>1</code> an <code>LinSlave</code> gebunden. Besitzt das Attribut:\n<ul class=\"fig-list\"><li><code>+ responseErrorPosition: Int</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzspezifikation. Das Diagramm modelliert Konfigurationsstrukturen für den LIN-Bus; die Parameter steuern die zeitliche Basis für das Scheduling des LIN-Masters sowie Fehleranzeigeposition und Knotenadressierung (NAD) auf Slave-Seite.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die AUTOSAR-Systembeschreibung (System Template). Bei der Konfiguration eines LIN-Clusters müssen Instanzen entweder als <code>LinMaster</code> oder <code>LinSlave</code> ausgeprägt werden. Ein <code>LinSlave</code> verlangt zwingend genau eine komponierte <code>LinErrorResponse</code> (Kardinalität 1) zur Festlegung der Fehlerposition im LIN-Frame. Die Zeitbasis-Attribute des Masters sind optional ([0..1]).</p>"}], "trans": [{"from": "FIG-0846cb7761e0b7bf", "to": "FIG-27ed5701146fecd2", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
